import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"What is CZero","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/what-is-czero.md","filePath":"en/guide/what-is-czero.md","lastUpdated":1785861127000}'),i={name:"en/guide/what-is-czero.md"};function n(s,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="what-is-czero" tabindex="-1">What is CZero <a class="header-anchor" href="#what-is-czero" aria-label="Permalink to &quot;What is CZero&quot;">​</a></h1><p>CZero is an Android root module that cleans the cache of frequently used apps, and adds background suppression, empty-folder cleanup, F2FS garbage collection and fstrim.</p><p>The module has no resident service — an extremely lightweight scheduling process triggers every task according to <code>config.json</code>, and configuration changes take effect immediately. Day-to-day operation goes through the native companion app <strong>CZeroX</strong>.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Over time, app caches and lingering background processes eat up storage and memory, and the device gradually slows down with less free space. CZero handles cleaning and suppression automatically in the background on a schedule, keeping the device clean and responsive without manual effort.</p><h2 id="design-principles" tabindex="-1">Design principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design principles&quot;">​</a></h2><ul><li><strong>No resident service</strong> — no Java process stays running; scheduling is handled by a tiny native process at near-zero cost, and cleaners exit as soon as they finish.</li><li><strong>Single source of truth</strong> — all behavior lives in one <code>config.json</code>, with no intermediate derived files.</li><li><strong>Instant effect</strong> — config changes hot-reload automatically; a broken config keeps the last-good job set and never interrupts service.</li><li><strong>Native frontend</strong> — day-to-day operation goes through the native CZeroX app, no WebUI.</li></ul><h2 id="where-things-live" tabindex="-1">Where things live <a class="header-anchor" href="#where-things-live" aria-label="Permalink to &quot;Where things live&quot;">​</a></h2><p>The module and its configuration live under <code>/data/adb/modules/CZero/</code>, where <code>config.json</code> is the only file you need to care about — edit it through CZeroX day to day. Stats and logs sit in the same directory and are removed along with the module when you uninstall.</p><p>The <strong>recycle bin</strong> produced by cleaning is not inside the module directory; it lives in the <code>Recycle</code> folder on internal storage, where cleaned files stay recoverable for 7 days. See <a href="/en/guide/features#recycle-bin-restore">Features · Recycle bin &amp; restore</a>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Android 9+ (API 28), <code>arm64-v8a</code></li><li>Root via Magisk, KernelSU, or APatch</li><li>F2FS <code>/data</code> partition (only for the GC feature; everything else works regardless)</li></ul><p>Ready? Head to <a href="/en/guide/getting-started">Install &amp; Setup</a>.</p>',13)])])}const p=a(i,[["render",n]]);export{u as __pageData,p as default};
